def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    nxt = n + 1
    op = [h[1] for h in history]
    my = [h[0] for h in history]
    opD = op.count('D')
    opC = n - opD
    myD = my.count('D')
    recent8 = op[-8:] if n >= 8 else op
    rD = recent8.count('D')
    last_o = op[-1]
    # Endgame: take advantage in final rounds.
    if nxt >= 98:
        return 'D'
    if nxt >= 95:
        if last_o == 'D':
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'
    if n < 3:
        if opD == 0:
            return 'C'
        return 'D' if last_o == 'D' else 'C'
    # Detect mostly- or all-cooperative opponent: cooperate long-term.
    if opD == 0:
        # Rarely probe to gain 5, only if safe.
        if n >= 12 and nxt < 90 and nxt % 17 == 0:
            return 'D'
        return 'C'
    if opD <= 1 and n >= 6:
        if last_o == 'D':
            return 'D'
        return 'C'
    # Heavy defector: punish hard.
    if opD * 3 >= n * 2:
        if last_o == 'D':
            return 'D'
        return 'D' if rng.random() < 0.85 else 'C'
    # Moderate defection rate: retaliate on last D, forgive mostly.
    if last_o == 'D':
        # If we're in a mutual-defection run, try to break it.
        if n >= 3 and my[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'
        # If recent defections were frequent, continue punishing.
        if rD >= 3:
            return 'D'
        # Otherwise retaliate but with some forgiveness.
        return 'D' if rng.random() < 0.8 else 'C'
    # Last opponent was C.
    # If we've been defecting a lot and they've been nice, ease off to keep them cooperating.
    if opD * 4 < n and myD * 3 > opD + 2:
        return 'C'
    # If recent pattern shows occasional hidden defection, retaliate lightly.
    if rD >= 2 and n >= 8:
        return 'D' if rng.random() < 0.4 else 'C'
    return 'C'
